func (u *SystemFunctionUpsertBulk) Update(set func(*SystemFunctionUpsert)) *SystemFunctionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&SystemFunctionUpsert{UpdateSet: update})
	}))
	return u
}

